import React from 'react';
import { Routes, Route } from 'react-router-dom'; // Import Outlet
import Home from './Pages/Home';
import BusinessForm from './components/BusinessFrom';
import Login from './Pages/Login';
import Register from './Pages/Register';
import PrivateRoute from './private/Private';
import LandingPage from './Pages/LandingPage';
import About from './Pages/About';
import ErrorBoundary from './components/ErrorBoundary';

const App: React.FC = () => {
  return (
    <ErrorBoundary>
      <div className="app-container">
        <Routes>
          {/* Public Routes */}
          <Route path="/" element={<Home />} /> {/* Make the home route specific */}
          <Route path="/auth/login" element={<Login />} />
          <Route path="/auth/register" element={<Register />} />
          <Route path="/about" element={<About />} />

          {/* Protected Routes */}
          <Route element={<PrivateRoute />}> {/* No need for children prop */}
            <Route path="/landing-page" element={<LandingPage />} />
            <Route path="/business-form" element={<BusinessForm />} />
          </Route>

          {/* No need for a separate error route if using ErrorBoundary */}
        </Routes>
      </div>
    </ErrorBoundary>
  );
};

export default App;