import React, { useState, FormEvent } from "react";
import { useNavigate } from "react-router-dom";
import { useAuth } from "../Provider/Provider";
import { Alert, TextField, Button, CircularProgress, Box, Typography } from "@mui/material";

const Login: React.FC = () => {
  const { userLogin, userGoogleLogin } = useAuth();
  const navigate = useNavigate();
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const googleLogo = 'AI-Driven-Business-Tool/front_end/public/assets/google-logo.png';

  const handleForm = async (e: FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    setError(null);

    try {
      setLoading(true);
      await userLogin(email, password);
      navigate("/landing-page");
    } catch (err) {
      setError(err instanceof Error ? err.message : "Login failed");
    } finally {
      setLoading(false);
    }
  };

  const handleGoogleLogin = async () => {
    setError(null);
    try {
      setLoading(true);
      await userGoogleLogin();
      navigate("/landing-page");
    } catch (err) {
      setError(err instanceof Error ? err.message : "Google login failed");
    } finally {
      setLoading(false);
    }
  };

  return (
    <Box
      sx={{
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
        minHeight: "100vh", // Use MUI's way for full viewport height
      }}
    >
      <Box
        sx={{
          maxWidth: 400,
          width: "100%",
          padding: 4,
          borderRadius: 2,
          boxShadow: 3,
          bgcolor: "white", // Use MUI's bgcolor
        }}
      >
        <Typography variant="h4" align="center" gutterBottom>
          Sign in
        </Typography>

        {loading && (
          <Box sx={{ display: "flex", justifyContent: "center" }}>
            <CircularProgress /> {/* Use MUI's CircularProgress */}
          </Box>
        )}

        {error && <Alert severity="error" sx={{ mt: 2 }}>{error}</Alert>}

        <form onSubmit={handleForm} noValidate>
          <TextField
            label="Email address"
            type="email"
            autoComplete="email"
            required
            fullWidth
            margin="normal"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
          />
          <TextField
            label="Password"
            type="password"
            autoComplete="current-password"
            required
            fullWidth
            margin="normal"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
          />

          <Button
            type="submit"
            variant="contained"
            color="primary"
            fullWidth
            disabled={loading}
            sx={{ mt: 2 }}
          >
            {loading ? "Signing in..." : "Sign in"}
          </Button>
        </form>

        <Button
          onClick={handleGoogleLogin}
          variant="contained"
          color="error" // Use MUI color prop
          fullWidth
          disabled={loading}
          startIcon={<img src={googleLogo} alt="Google logo" />}
          sx={{ mt: 2 }}
        >
          {loading ? "Signing in with Google..." : "Sign in with Google"}
        </Button>
      </Box>
    </Box>
  );
};

export default Login;