import React, { createContext, useContext, useEffect, useState, ReactNode } from "react";
import {
//   Auth,
  UserCredential,
  User,
  GoogleAuthProvider,
  createUserWithEmailAndPassword,
  onAuthStateChanged,
  sendPasswordResetEmail,
  signInWithEmailAndPassword,
  signInWithPopup,
  signOut,
  updateProfile
} from "firebase/auth";
import auth from "../Firebase/Firebase.config";

// Define types for the context
interface AuthContextType {
  user: User | null;
  loading: boolean;
  email: string;
  setEmail: React.Dispatch<React.SetStateAction<string>>;
  userRegister: (email: string, password: string) => Promise<UserCredential>;
  userLogin: (email: string, password: string) => Promise<UserCredential>;
  userGoogleLogin: () => Promise<UserCredential>;
  userLogout: () => Promise<void>;
  UpdateUserProfile: (updateData: { displayName?: string; photoURL?: string }) => Promise<void>;
  userForgePassword: (email: string) => Promise<void>;
}

// Define props interface
interface AuthProviderProps {
  children: ReactNode;
}

// Create the context
export const AuthContext = createContext<AuthContextType>({} as AuthContextType);

// Create Google Auth Provider
const googleProvider = new GoogleAuthProvider();

// Custom hook for using auth context
export const useAuth = () => {
  const context = useContext(AuthContext);
  if (!context) {
    throw new Error("useAuth must be used within an AuthProvider");
  }
  return context;
};

const AuthProvider: React.FC<AuthProviderProps> = ({ children }) => {
  const [user, setUser] = useState<User | null>(null);
  const [loading, setLoading] = useState<boolean>(true);
  const [email, setEmail] = useState<string>("");

  // User Register method
  const userRegister = async (email: string, password: string): Promise<UserCredential> => {
    setLoading(true);
    try {
      return await createUserWithEmailAndPassword(auth, email, password);

    } catch (error) {
      throw error;
    } finally {
      setLoading(false);
    }
  };

  // User Login method
  const userLogin = async (email: string, password: string) => {
    setLoading(true);
    try {
      return await signInWithEmailAndPassword(auth, email, password); // No setLoading here
    } catch (error) {
      throw error; // Re-throw the error to be handled by the component
    } finally {
      setLoading(false); // Always set loading to false here
    }
  };
  
  // Google Login method
  const userGoogleLogin = async (): Promise<UserCredential> => {
    setLoading(true);
    try {
      const result = await signInWithPopup(auth, googleProvider);
      setLoading(false);
      return result;
    } catch (error) {
      setLoading(false);
      throw error;
    }
  };

  // Logout method
  const userLogout = async (): Promise<void> => {
    setLoading(true);
    try {
      await signOut(auth);
      setLoading(false);
    } catch (error) {
      setLoading(false);
      throw error;
    }
  };

  // Update Profile method
  const UpdateUserProfile = async (updateData: { displayName?: string | null; photoURL?: string | null; }) => {
    if (!auth.currentUser) {
      throw new Error("No user is currently signed in");
    }
    try {
      await updateProfile(auth.currentUser, updateData);
    } catch (error) {
      throw error;
    }
  };

  // Password Reset method
  const userForgePassword = async (email: string): Promise<void> => {
    try {
      await sendPasswordResetEmail(auth, email);
    } catch (error) {
      throw error;
    }
  };

  // Observer for auth state changes
  useEffect(() => {
    const unsubscribe = onAuthStateChanged(auth, (currentUser) => {
      setUser(currentUser);
      setLoading(false);
    });

    return () => unsubscribe();
  }, []);

  // Context value
  const authInfo: AuthContextType = {
    user,
    loading,
    email,
    setEmail,
    userRegister,
    userLogin,
    userGoogleLogin,
    userLogout,
    UpdateUserProfile,
    userForgePassword,
  };

  return (
    <AuthContext.Provider value={authInfo}>
      {children}
    </AuthContext.Provider>
  );
};

export { AuthProvider };
