import { useContext, useState, FormEvent } from "react";
import { Link, useNavigate, useLocation } from "react-router-dom";
import { AuthContext } from "../Provider/Provider";
// import toast from "react-hot-toast";
import { IoMdEyeOff } from "react-icons/io";
import { IoEye } from "react-icons/io5";
import { FcGoogle } from "react-icons/fc";
import { Alert } from "@mui/material"; // Import Alert
import { UserCredential } from "firebase/auth"; // Import Firebase types



interface AuthContextType {
  userRegister: (email: string, password: string) => Promise<UserCredential>;
  UpdateUserProfile: (profile: { displayName: string; photoURL: string }) => Promise<void>;
  userGoogleLogin: () => Promise<UserCredential>;
}

const Register = () => {
  const { userRegister, UpdateUserProfile, userGoogleLogin } = useContext(AuthContext) as AuthContextType;
  const navigate = useNavigate();
  const location = useLocation();
  const [show, setShow] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [formData, setFormData] = useState({
    name: "",
    photo: "",
    email: "",
    password: "",
  });

  const handleShowPass = () => setShow(!show);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    setFormData((prev) => ({ ...prev, [name]: value }));
  };


  const handleSubmit = async (e: FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    setLoading(true);

    try {
      await userRegister(formData.email, formData.password);
      await UpdateUserProfile({ displayName: formData.name, photoURL: formData.photo });
      navigate("/landing-page");
    } catch (error) {
      setError(error instanceof Error ? error.message : "Registration failed.");
    } finally {
      setLoading(false);
    }
  };

  const handleGoogleSignIn = () => {
    userGoogleLogin()
      .then(() => {
        const from = (location.state as { from?: { pathname: string } })?.from?.pathname || '/';
        navigate(from);
      })
      .catch((err: Error) => {
        setError(err instanceof Error ? err.message : "Google registration failed.");

      });
  };

  return (
    <div className="min-h-screen flex justify-center my-10 items-center">
      <div className="card bg-base-100 w-full md:max-w-lg max-w-sm rounded-lg py-10 shrink-0 shadow-2xl shadow-sky-300 border border-sky-200">
        <h2 className="text-2xl font-semibold text-center">
          Register your account
        </h2>
        {error && <Alert severity="error" sx={{ mt: 2 }}>{error}</Alert>}
        <form onSubmit={handleSubmit} className="card-body">

          <div className="form-control">
            <label className="label">
              <span className="label-text">Your Name</span>
            </label>
            <input
              type="text"
              name="name"
              placeholder="Enter your name"
              className="input input-bordered"
              required
              value={formData.name} // Use form data
              onChange={handleChange}
            />
          </div>
          <div className="form-control">
            <label className="label">
              <span className="label-text">Photo URL</span>
            </label>
            <input
              type="text"
              name="photo"
              placeholder="Enter your photo URL"
              className="input input-bordered"
              required
              value={formData.photo} // Use form data
              onChange={handleChange}
            />
          </div>
          <div className="form-control">
            <label className="label">
              <span className="label-text">Email</span>
            </label>
            <input
              type="email"
              name="email"
              placeholder="email"
              className="input input-bordered"
              required
              value={formData.email} // Use form data
              onChange={handleChange}
            />
          </div>
          <div className="form-control relative">
            <label className="label">
              <span className="label-text">Password</span>
            </label>
            <input
              type={show ? "text" : "password"}
              name="password"
              placeholder="password"
              className="input input-bordered"
              required
              value={formData.password} // Use form data
              onChange={handleChange}
            />
            <button
              type="button"
              onClick={handleShowPass}
              className="text-xl cursor-pointer absolute top-12 right-5"
            >
              {show ? <IoEye /> : <IoMdEyeOff />}
            </button>
          </div>
          <div className="form-control mt-6">
            <button
              className="btn btn-ghost bg-sky-500 text-white hover:text-slate-950"
              disabled={loading} // Disable while loading
            >
              {loading ? "Registering..." : "Register"} {/* Loading indicator */}
            </button>
          </div>

        </form>
        <h2 className="font-normal text-center">
          Already Have an account?{" "}
          <Link className="text-sky-500" to="/auth/login">
            Login
          </Link>
        </h2>
        <button
          onClick={handleGoogleSignIn}
          className="btn w-56 mx-auto mt-4"
        >
          <span className="text-2xl">
            <FcGoogle />
          </span>
          Register with Google
        </button>
      </div>
    </div>
  );
};

export default Register;

